import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}

        best_value = None
        best_ids = None
        best_selected = None
        for selected in combinations(
                (job for job in jobs if job["id"] not in blocked), k):
            ids = tuple(sorted(job["id"] for job in selected))
            if not mandatory.issubset(ids):
                continue

            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not (low <= counts.get(group, 0) <= high)
                   for group, (low, high) in data.get("quotas", {}).items()):
                continue

            active = []
            compatible = True
            for job in sorted(selected,
                               key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    compatible = False
                    break
            if not compatible:
                continue

            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids, best_selected = value, ids, selected

        if best_selected is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        domains = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, [])
                              and (name not in pins or
                                   row["version"] == pins[name]))
            domains.append([None] + versions)

        best_vector = None
        best_versions = None
        for assignment in product(*domains):
            chosen = {name: version for name, version in zip(names, assignment)
                      if version is not None}
            if any(name not in chosen or
                   not (bounds[0] <= chosen[name] <= bounds[1])
                   for name, bounds in roots.items()):
                continue

            edges = {name: [] for name in chosen}
            valid = True
            for name, version in chosen.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if (other not in chosen or
                            not (dep["min"] <= chosen[other] <= dep["max"])):
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                pending.extend(edges.get(name, []))
            if reachable != set(chosen):
                continue

            finished = set()
            active = set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in reachable):
                continue

            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = chosen

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start = data["start"]
        initial_mask = required_bit.get(source, 0)
        initial = (source, data["coupons"], initial_mask)
        best = {initial: start}
        queue = [(start, source, data["coupons"], initial_mask)]

        while queue:
            arrival, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full_mask and
                    remaining == 0):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, remaining - 1))
                next_mask = mask | required_bit.get(edge["v"], 0)
                for duration, next_remaining in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_remaining, next_mask)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"],
                                              next_remaining, next_mask))
        return {"arrival": None}
    return solve


